	// Verilator lint_on UNUSED
	// }}}
	// Bus wbflash
	// {{{
	// Wishbone definitions for bus wbflash, component crossflash
	// Verilator lint_off UNUSED
	wire		wbflash_crossflash_cyc, wbflash_crossflash_stb, wbflash_crossflash_we;
	wire	[22:0]	wbflash_crossflash_addr;
	wire	[31:0]	wbflash_crossflash_data;
	wire	[3:0]	wbflash_crossflash_sel;
	wire		wbflash_crossflash_stall, wbflash_crossflash_ack, wbflash_crossflash_err;
	wire	[31:0]	wbflash_crossflash_idata;
	// Verilator lint_on UNUSED
	// Wishbone definitions for bus wbflash, component sdio
	// Verilator lint_off UNUSED
	wire		wbflash_sdio_cyc, wbflash_sdio_stb, wbflash_sdio_we;
	wire	[22:0]	wbflash_sdio_addr;
	wire	[31:0]	wbflash_sdio_data;
	wire	[3:0]	wbflash_sdio_sel;
	wire		wbflash_sdio_stall, wbflash_sdio_ack, wbflash_sdio_err;
	wire	[31:0]	wbflash_sdio_idata;
	// Verilator lint_on UNUSED
	// Wishbone definitions for bus wbflash, component flash
	// Verilator lint_off UNUSED
	wire		wbflash_flash_cyc, wbflash_flash_stb, wbflash_flash_we;
	wire	[22:0]	wbflash_flash_addr;
	wire	[31:0]	wbflash_flash_data;
	wire	[3:0]	wbflash_flash_sel;
	wire		wbflash_flash_stall, wbflash_flash_ack, wbflash_flash_err;
	wire	[31:0]	wbflash_flash_idata;
	// Verilator lint_on UNUSED
	// }}}
	// }}}
	////////////////////////////////////////////////////////////////////////
	//
	// Peripheral address decoding, bus handling
	// {{{
	//
	// BUS-LOGIC for wbwide
	// {{{
	//
	// No class SINGLE peripherals on the "wbwide" bus
	//

	//
	// No class DOUBLE peripherals on the "wbwide" bus
	//

	// info: @ERROR.WIRE for crossflash matches the buses error name, wbwide_crossflash_err
	// info: @ERROR.WIRE for crossbus matches the buses error name, wbwide_crossbus_err
	assign	wbwide_bkram_err= 1'b0;
	assign	wbwide_sdram_err= 1'b0;
	//
	// Connect the wbwide bus components together using the wbxbar()
	//
	//
	wbxbar #(
		.NM(6), .NS(4), .AW(26), .DW(128),
		.SLAVE_ADDR({
			// Address width    = 26
			// Address LSBs     = 4
			{ 26'h2000000 }, //      sdram: 0x20000000
			{ 26'h1000000 }, //      bkram: 0x10000000
			{ 26'h0800000 }, //   crossbus: 0x08000000
			{ 26'h0000000 }  // crossflash: 0x00000000
		}),
		.SLAVE_MASK({
			// Address width    = 26
			// Address LSBs     = 4
			{ 26'h2000000 }, //      sdram
			{ 26'h3800000 }, //      bkram
			{ 26'h3800000 }, //   crossbus
			{ 26'h3800000 }  // crossflash
		}),
		.OPT_DBLBUFFER(1'b1))
	wbwide_xbar(
		.i_clk(i_clk), .i_reset(i_reset),
		.i_mcyc({
			wbwide_edidm_cyc,
			wbwide_sdio_cyc,
			wbwide_zip_cyc,
			wbwide_hdmi_cyc,
			wbwide_wbu_arbiter_cyc,
			wbwide_i2cm_cyc
		}),
		.i_mstb({
			wbwide_edidm_stb,
			wbwide_sdio_stb,
			wbwide_zip_stb,
			wbwide_hdmi_stb,
			wbwide_wbu_arbiter_stb,
			wbwide_i2cm_stb
		}),
		.i_mwe({
			wbwide_edidm_we,
			wbwide_sdio_we,
			wbwide_zip_we,
			wbwide_hdmi_we,
			wbwide_wbu_arbiter_we,
			wbwide_i2cm_we
		}),
		.i_maddr({
			wbwide_edidm_addr,
			wbwide_sdio_addr,
			wbwide_zip_addr,
			wbwide_hdmi_addr,
			wbwide_wbu_arbiter_addr,
			wbwide_i2cm_addr
		}),
		.i_mdata({
			wbwide_edidm_data,
			wbwide_sdio_data,
			wbwide_zip_data,
			wbwide_hdmi_data,
			wbwide_wbu_arbiter_data,
			wbwide_i2cm_data
		}),
		.i_msel({
			wbwide_edidm_sel,
			wbwide_sdio_sel,
			wbwide_zip_sel,
			wbwide_hdmi_sel,
			wbwide_wbu_arbiter_sel,
			wbwide_i2cm_sel
		}),
		.o_mstall({
			wbwide_edidm_stall,
			wbwide_sdio_stall,
			wbwide_zip_stall,
			wbwide_hdmi_stall,
			wbwide_wbu_arbiter_stall,
			wbwide_i2cm_stall
		}),
		.o_mack({
			wbwide_edidm_ack,
			wbwide_sdio_ack,
			wbwide_zip_ack,
			wbwide_hdmi_ack,
			wbwide_wbu_arbiter_ack,
			wbwide_i2cm_ack
		}),
		.o_mdata({
			wbwide_edidm_idata,
			wbwide_sdio_idata,
			wbwide_zip_idata,
			wbwide_hdmi_idata,
			wbwide_wbu_arbiter_idata,
			wbwide_i2cm_idata
		}),
		.o_merr({
			wbwide_edidm_err,
			wbwide_sdio_err,
			wbwide_zip_err,
			wbwide_hdmi_err,
			wbwide_wbu_arbiter_err,
			wbwide_i2cm_err
		}),
		// Slave connections
		.o_scyc({
			wbwide_sdram_cyc,
			wbwide_bkram_cyc,
			wbwide_crossbus_cyc,
			wbwide_crossflash_cyc
		}),
		.o_sstb({
			wbwide_sdram_stb,
			wbwide_bkram_stb,
			wbwide_crossbus_stb,
			wbwide_crossflash_stb
		}),
		.o_swe({
			wbwide_sdram_we,
			wbwide_bkram_we,
			wbwide_crossbus_we,
			wbwide_crossflash_we
		}),
		.o_saddr({
			wbwide_sdram_addr,
			wbwide_bkram_addr,
			wbwide_crossbus_addr,
			wbwide_crossflash_addr
		}),
		.o_sdata({
			wbwide_sdram_data,
			wbwide_bkram_data,
			wbwide_crossbus_data,
			wbwide_crossflash_data
		}),
		.o_ssel({
			wbwide_sdram_sel,
			wbwide_bkram_sel,
			wbwide_crossbus_sel,
			wbwide_crossflash_sel
		}),
		.i_sstall({
			wbwide_sdram_stall,
			wbwide_bkram_stall,
			wbwide_crossbus_stall,
			wbwide_crossflash_stall
		}),
		.i_sack({
			wbwide_sdram_ack,
			wbwide_bkram_ack,
			wbwide_crossbus_ack,
			wbwide_crossflash_ack
		}),
		.i_sdata({
			wbwide_sdram_idata,
			wbwide_bkram_idata,
			wbwide_crossbus_idata,
			wbwide_crossflash_idata
		}),
		.i_serr({
			wbwide_sdram_err,
			wbwide_bkram_err,
			wbwide_crossbus_err,
			wbwide_crossflash_err
		})
		);

	// End of bus logic for wbwide
	// }}}
	//
	// BUS-LOGIC for wb32
	// {{{
	//
	// wb32 Bus logic to handle SINGLE slaves
	//
	reg		r_wb32_sio_ack;
	reg	[31:0]	r_wb32_sio_data;

	assign	wb32_sio_stall = 1'b0;

	initial r_wb32_sio_ack = 1'b0;
	always	@(posedge i_clk)
		r_wb32_sio_ack <= (wb32_sio_stb);
	assign	wb32_sio_ack = r_wb32_sio_ack;

	always	@(posedge i_clk)
	casez( wb32_sio_addr[3:0] )
	4'h0: r_wb32_sio_data <= wb32_buildtime_idata;
	4'h1: r_wb32_sio_data <= wb32_buserr_idata;
	4'h2: r_wb32_sio_data <= wb32_genclk_idata;
	4'h3: r_wb32_sio_data <= wb32_genclkfb_idata;
	4'h4: r_wb32_sio_data <= wb32_gpio_idata;
	4'h5: r_wb32_sio_data <= wb32_netclockctr_idata;
	4'h6: r_wb32_sio_data <= wb32_nettxctr_idata;
	4'h7: r_wb32_sio_data <= wb32_pwrcount_idata;
	4'h8: r_wb32_sio_data <= wb32_rtccount_idata;
	4'h9: r_wb32_sio_data <= wb32_rtcdate_idata;
	4'ha: r_wb32_sio_data <= wb32_spio_idata;
	4'hb: r_wb32_sio_data <= wb32_sysclk_idata;
	4'hc: r_wb32_sio_data <= wb32_version_idata;
	default: r_wb32_sio_data <= wb32_version_idata;
	endcase
	assign	wb32_sio_idata = r_wb32_sio_data;


	//
	// Now to translate this logic to the various SIO slaves
	//
	// In this case, the SIO bus has the prefix wb32_sio
	// and all of the slaves have various wires beginning
	// with their own respective bus prefixes.
	// Our goal here is to make certain that all of
	// the slave bus inputs match the SIO bus wires
	assign	wb32_buildtime_cyc = wb32_sio_cyc;
	assign	wb32_buildtime_stb = wb32_sio_stb && (wb32_sio_addr[ 3: 0] ==  4'h0);  // 0x000
	assign	wb32_buildtime_we  = wb32_sio_we;
	assign	wb32_buildtime_data= wb32_sio_data;
	assign	wb32_buildtime_sel = wb32_sio_sel;
	assign	wb32_buserr_cyc = wb32_sio_cyc;
	assign	wb32_buserr_stb = wb32_sio_stb && (wb32_sio_addr[ 3: 0] ==  4'h1);  // 0x004
	assign	wb32_buserr_we  = wb32_sio_we;
	assign	wb32_buserr_data= wb32_sio_data;
	assign	wb32_buserr_sel = wb32_sio_sel;
	assign	wb32_genclk_cyc = wb32_sio_cyc;
	assign	wb32_genclk_stb = wb32_sio_stb && (wb32_sio_addr[ 3: 0] ==  4'h2);  // 0x008
	assign	wb32_genclk_we  = wb32_sio_we;
	assign	wb32_genclk_data= wb32_sio_data;
	assign	wb32_genclk_sel = wb32_sio_sel;
	assign	wb32_genclkfb_cyc = wb32_sio_cyc;
	assign	wb32_genclkfb_stb = wb32_sio_stb && (wb32_sio_addr[ 3: 0] ==  4'h3);  // 0x00c
	assign	wb32_genclkfb_we  = wb32_sio_we;
	assign	wb32_genclkfb_data= wb32_sio_data;
	assign	wb32_genclkfb_sel = wb32_sio_sel;
	assign	wb32_gpio_cyc = wb32_sio_cyc;
	assign	wb32_gpio_stb = wb32_sio_stb && (wb32_sio_addr[ 3: 0] ==  4'h4);  // 0x010
	assign	wb32_gpio_we  = wb32_sio_we;
	assign	wb32_gpio_data= wb32_sio_data;
	assign	wb32_gpio_sel = wb32_sio_sel;
	assign	wb32_netclockctr_cyc = wb32_sio_cyc;
	assign	wb32_netclockctr_stb = wb32_sio_stb && (wb32_sio_addr[ 3: 0] ==  4'h5);  // 0x014
	assign	wb32_netclockctr_we  = wb32_sio_we;
	assign	wb32_netclockctr_data= wb32_sio_data;
	assign	wb32_netclockctr_sel = wb32_sio_sel;
	assign	wb32_nettxctr_cyc = wb32_sio_cyc;
	assign	wb32_nettxctr_stb = wb32_sio_stb && (wb32_sio_addr[ 3: 0] ==  4'h6);  // 0x018
	assign	wb32_nettxctr_we  = wb32_sio_we;
	assign	wb32_nettxctr_data= wb32_sio_data;
	assign	wb32_nettxctr_sel = wb32_sio_sel;
	assign	wb32_pwrcount_cyc = wb32_sio_cyc;
	assign	wb32_pwrcount_stb = wb32_sio_stb && (wb32_sio_addr[ 3: 0] ==  4'h7);  // 0x01c
	assign	wb32_pwrcount_we  = wb32_sio_we;
	assign	wb32_pwrcount_data= wb32_sio_data;
	assign	wb32_pwrcount_sel = wb32_sio_sel;
	assign	wb32_rtccount_cyc = wb32_sio_cyc;
	assign	wb32_rtccount_stb = wb32_sio_stb && (wb32_sio_addr[ 3: 0] ==  4'h8);  // 0x020
	assign	wb32_rtccount_we  = wb32_sio_we;
	assign	wb32_rtccount_data= wb32_sio_data;
	assign	wb32_rtccount_sel = wb32_sio_sel;
	assign	wb32_rtcdate_cyc = wb32_sio_cyc;
	assign	wb32_rtcdate_stb = wb32_sio_stb && (wb32_sio_addr[ 3: 0] ==  4'h9);  // 0x024
	assign	wb32_rtcdate_we  = wb32_sio_we;
	assign	wb32_rtcdate_data= wb32_sio_data;
	assign	wb32_rtcdate_sel = wb32_sio_sel;
	assign	wb32_spio_cyc = wb32_sio_cyc;
	assign	wb32_spio_stb = wb32_sio_stb && (wb32_sio_addr[ 3: 0] ==  4'ha);  // 0x028
	assign	wb32_spio_we  = wb32_sio_we;
	assign	wb32_spio_data= wb32_sio_data;
	assign	wb32_spio_sel = wb32_sio_sel;
	assign	wb32_sysclk_cyc = wb32_sio_cyc;
	assign	wb32_sysclk_stb = wb32_sio_stb && (wb32_sio_addr[ 3: 0] ==  4'hb);  // 0x02c
	assign	wb32_sysclk_we  = wb32_sio_we;
	assign	wb32_sysclk_data= wb32_sio_data;
	assign	wb32_sysclk_sel = wb32_sio_sel;
	assign	wb32_version_cyc = wb32_sio_cyc;
	assign	wb32_version_stb = wb32_sio_stb && (wb32_sio_addr[ 3: 0] ==  4'hc);  // 0x030
	assign	wb32_version_we  = wb32_sio_we;
	assign	wb32_version_data= wb32_sio_data;
	assign	wb32_version_sel = wb32_sio_sel;
	//
	// wb32 Bus logic to handle 5 DOUBLE slaves
	//
	//
	reg	[1:0]	r_wb32_dio_ack;
	// # dlist = 5, nextlg(#dlist) = 3
	reg	[2:0]	r_wb32_dio_bus_select;
	reg	[31:0]	r_wb32_dio_data;

	// DOUBLE peripherals are not allowed to stall.
	assign	wb32_dio_stall = 1'b0;

	// DOUBLE peripherals return their acknowledgments in two
	// clocks--always, allowing us to collect this logic together
	// in a slave independent manner.  Here, the acknowledgment
	// is treated as a two stage shift register, cleared on any
	// reset, or any time the cycle line drops.  (Dropping the
	// cycle line aborts the transaction.)
	initial	r_wb32_dio_ack = 0;
	always	@(posedge i_clk)
	if (i_reset || !wb32_dio_cyc)
		r_wb32_dio_ack <= 0;
	else
		r_wb32_dio_ack <= { r_wb32_dio_ack[0], (wb32_dio_stb) };
	assign	wb32_dio_ack = r_wb32_dio_ack[1];

	// Since it costs us two clocks to go through this
	// logic, we'll take one of those clocks here to set
	// a selection index, and then on the next clock we'll
	// use this index to select from among the vaious
	// possible bus return values
	always @(posedge i_clk)
	casez(wb32_dio_addr[6:4])
	3'b0_00: r_wb32_dio_bus_select <= 3'd0;
	3'b0_01: r_wb32_dio_bus_select <= 3'd1;
	3'b0_10: r_wb32_dio_bus_select <= 3'd2;
	3'b0_11: r_wb32_dio_bus_select <= 3'd3;
	3'b1_??: r_wb32_dio_bus_select <= 3'd4;
	default: r_wb32_dio_bus_select <= 0;
	endcase

	always	@(posedge i_clk)
	casez(r_wb32_dio_bus_select)
	3'd0: r_wb32_dio_data <= wb32_edids_idata;
	3'd1: r_wb32_dio_data <= wb32_i2cs_idata;
	3'd2: r_wb32_dio_data <= wb32_rtc_idata;
	3'd3: r_wb32_dio_data <= wb32_sio_idata;
	3'd4: r_wb32_dio_data <= wb32_edidslv_idata;
	default: r_wb32_dio_data <= wb32_edidslv_idata;
	endcase

	assign	wb32_dio_idata = r_wb32_dio_data;

	assign	wb32_edids_cyc = wb32_dio_cyc;
	assign	wb32_edids_stb = wb32_dio_stb && ((wb32_dio_addr[ 6: 4] &  3'h7) ==  3'h0);  // 0x000 - 0x00f
	assign	wb32_edids_we  = wb32_dio_we;
	assign	wb32_edids_addr= wb32_dio_addr;
	assign	wb32_edids_data= wb32_dio_data;
	assign	wb32_edids_sel = wb32_dio_sel;
	assign	wb32_i2cs_cyc = wb32_dio_cyc;
	assign	wb32_i2cs_stb = wb32_dio_stb && ((wb32_dio_addr[ 6: 4] &  3'h7) ==  3'h1);  // 0x040 - 0x04f
	assign	wb32_i2cs_we  = wb32_dio_we;
	assign	wb32_i2cs_addr= wb32_dio_addr;
	assign	wb32_i2cs_data= wb32_dio_data;
	assign	wb32_i2cs_sel = wb32_dio_sel;
	assign	wb32_rtc_cyc = wb32_dio_cyc;
	assign	wb32_rtc_stb = wb32_dio_stb && ((wb32_dio_addr[ 6: 4] &  3'h7) ==  3'h2);  // 0x080 - 0x09f
	assign	wb32_rtc_we  = wb32_dio_we;
	assign	wb32_rtc_addr= wb32_dio_addr;
	assign	wb32_rtc_data= wb32_dio_data;
	assign	wb32_rtc_sel = wb32_dio_sel;
	assign	wb32_sio_cyc = wb32_dio_cyc;
	assign	wb32_sio_stb = wb32_dio_stb && ((wb32_dio_addr[ 6: 4] &  3'h7) ==  3'h3);  // 0x0c0 - 0x0ff
	assign	wb32_sio_we  = wb32_dio_we;
	assign	wb32_sio_addr= wb32_dio_addr;
	assign	wb32_sio_data= wb32_dio_data;
	assign	wb32_sio_sel = wb32_dio_sel;
	assign	wb32_edidslv_cyc = wb32_dio_cyc;
	assign	wb32_edidslv_stb = wb32_dio_stb && ((wb32_dio_addr[ 6: 4] &  3'h4) ==  3'h4);  // 0x100 - 0x1ff
	assign	wb32_edidslv_we  = wb32_dio_we;
	assign	wb32_edidslv_addr= wb32_dio_addr;
	assign	wb32_edidslv_data= wb32_dio_data;
	assign	wb32_edidslv_sel = wb32_dio_sel;
	assign	wb32_flashcfg_err= 1'b0;
	assign	wb32_zipscope_err= 1'b0;
	assign	wb32_uart_err= 1'b0;
	assign	wb32_cfg_err= 1'b0;
	assign	wb32_net_err= 1'b0;
	assign	wb32_dio_err= 1'b0;
	assign	wb32_hdmi_err= 1'b0;
	assign	wb32_mdio_err= 1'b0;
	//
	// Connect the wb32 bus components together using the wbxbar()
	//
	//
	wbxbar #(
		.NM(1), .NS(8), .AW(12), .DW(32),
		.SLAVE_ADDR({
			// Address width    = 12
			// Address LSBs     = 2
			{ 12'hc00 }, //     mdio: 0x3000
			{ 12'h800 }, //     hdmi: 0x2000
			{ 12'h600 }, // wb32_dio: 0x1800
			{ 12'h500 }, //      net: 0x1400
			{ 12'h400 }, //      cfg: 0x1000
			{ 12'h300 }, //     uart: 0x0c00
			{ 12'h200 }, // zipscope: 0x0800
			{ 12'h100 }  // flashcfg: 0x0400
		}),
		.SLAVE_MASK({
			// Address width    = 12
			// Address LSBs     = 2
			{ 12'hc00 }, //     mdio
			{ 12'hc00 }, //     hdmi
			{ 12'hf00 }, // wb32_dio
			{ 12'hf00 }, //      net
			{ 12'hf00 }, //      cfg
			{ 12'hf00 }, //     uart
			{ 12'hf00 }, // zipscope
			{ 12'hf00 }  // flashcfg
		}),
		.OPT_DBLBUFFER(1'b1))
	wb32_xbar(
		.i_clk(i_clk), .i_reset(i_reset),
		.i_mcyc({
			wb32_crossbus_cyc
		}),
		.i_mstb({
			wb32_crossbus_stb
		}),
		.i_mwe({
			wb32_crossbus_we
		}),
		.i_maddr({
			wb32_crossbus_addr
		}),
		.i_mdata({
			wb32_crossbus_data
		}),
		.i_msel({
			wb32_crossbus_sel
		}),
		.o_mstall({
			wb32_crossbus_stall
		}),
		.o_mack({
			wb32_crossbus_ack
		}),
		.o_mdata({
			wb32_crossbus_idata
		}),
		.o_merr({
			wb32_crossbus_err
		}),
		// Slave connections
		.o_scyc({
			wb32_mdio_cyc,
			wb32_hdmi_cyc,
			wb32_dio_cyc,
			wb32_net_cyc,
			wb32_cfg_cyc,
			wb32_uart_cyc,
			wb32_zipscope_cyc,
			wb32_flashcfg_cyc
		}),
		.o_sstb({
			wb32_mdio_stb,
			wb32_hdmi_stb,
			wb32_dio_stb,
			wb32_net_stb,
			wb32_cfg_stb,
			wb32_uart_stb,
			wb32_zipscope_stb,
			wb32_flashcfg_stb
		}),
		.o_swe({
			wb32_mdio_we,
			wb32_hdmi_we,
			wb32_dio_we,
