	//
	// BUS-LOGIC for wbu
	// {{{
	//
	// No class SINGLE peripherals on the "wbu" bus
	//

	//
	// No class DOUBLE peripherals on the "wbu" bus
	//

	// info: @ERROR.WIRE for wbu_arbiter matches the buses error name, wbu_wbu_arbiter_err
	assign	wbu_zip_err= 1'b0;
	//
	// Connect the wbu bus components together using the wbxbar()
	//
	//
	wbxbar #(
		.NM(2), .NS(2), .AW(29), .DW(32),
		.SLAVE_ADDR({
			// Address width    = 29
			// Address LSBs     = 2
			{ 29'h10000000 }, //         zip: 0x40000000
			{ 29'h00000000 }  // wbu_arbiter: 0x00000000
		}),
		.SLAVE_MASK({
			// Address width    = 29
			// Address LSBs     = 2
			{ 29'h18000000 }, //         zip
			{ 29'h10000000 }  // wbu_arbiter
		}),
		.OPT_DBLBUFFER(1'b1))
	wbu_xbar(
		.i_clk(i_clk), .i_reset(i_reset),
		.i_mcyc({
			wbu_cyc,
			netbus_cyc
		}),
		.i_mstb({
			wbu_stb,
			netbus_stb
		}),
		.i_mwe({
			wbu_we,
			netbus_we
		}),
		.i_maddr({
			wbu_addr,
			netbus_addr
		}),
		.i_mdata({
			wbu_data,
			netbus_data
		}),
		.i_msel({
			wbu_sel,
			netbus_sel
		}),
		.o_mstall({
			wbu_stall,
			netbus_stall
		}),
		.o_mack({
			wbu_ack,
			netbus_ack
		}),
		.o_mdata({
			wbu_idata,
			netbus_idata
		}),
		.o_merr({
			wbu_err,
			netbus_err
		}),
		// Slave connections
		.o_scyc({
			wbu_zip_cyc,
			wbu_wbu_arbiter_cyc
		}),
		.o_sstb({
			wbu_zip_stb,
			wbu_wbu_arbiter_stb
		}),
		.o_swe({
			wbu_zip_we,
			wbu_wbu_arbiter_we
		}),
		.o_saddr({
			wbu_zip_addr,
			wbu_wbu_arbiter_addr
		}),
		.o_sdata({
			wbu_zip_data,
			wbu_wbu_arbiter_data
		}),
		.o_ssel({
			wbu_zip_sel,
			wbu_wbu_arbiter_sel
		}),
		.i_sstall({
			wbu_zip_stall,
