	assign	wb32_rtccount_ack = wb32_rtccount_stb;

	initial	r_rtccount_data = 32'h0;
	always @(posedge i_clk)
		r_rtccount_data <= r_rtccount_data + 43;
	assign	wb32_rtccount_idata = r_rtccount_data;
	// }}}
	// }}}
`else	// RTCCOUNT_ACCESS
	// {{{
	// }}}
`endif	// RTCCOUNT_ACCESS

	always @(posedge i_clk)
	if (wbwide_zip_err)
	begin
		r_buserr_addr <= 0;
		r_buserr_addr[26-1:0] <= wbwide_zip_addr[26-1:0];
	end else if (wbu_err)
	begin
		r_buserr_addr <= 0;
		r_buserr_addr[29-1:0] <= wbu_addr[29-1:0];
	end
	assign	wb32_buserr_stall= 1'b0;
	assign	wb32_buserr_ack  = wb32_buserr_stb;
	assign	wb32_buserr_idata = { {(30-29){1'b0}},
			r_buserr_addr, 2'b00 };
`ifdef	ARBITRARY_CLOCK_GENERATOR_ACCESS
	// {{{
	////////////////////////////////////////////////////////////////////////
	//
	// Generic clock frequency generator
	// {{{
	initial	r_genclk_data = { 1'b1, DEF_GENCLK_FREQUENCY[29:0] };

	always @(posedge i_clk)
	if (i_reset)
		r_genclk_data <= { 1'b1, DEF_GENCLK_FREQUENCY[29:0] };
	else if (wb32_genclk_stb && wb32_genclk_we)
		r_genclk_data <= wb32_genclk_data[30:0];

	always @(posedge i_clk)
		r_genclk_ack <= wb32_genclk_stb;
	assign	wb32_genclk_ack   = r_genclk_ack;
	assign	wb32_genclk_stall = 1'b0;
	assign	wb32_genclk_idata = { i_genclk_pll_locked, r_genclk_data };
	assign	o_genclk_ce = r_genclk_data[30];

	genclk
	u_genclk(
		i_clk,
		{ 2'b00, r_genclk_data[29:0] },
		o_genclk_word,
		w_genclk_unused_stb
	);
	// }}}
`else	// ARBITRARY_CLOCK_GENERATOR_ACCESS
	// {{{
	// }}}
`endif	// ARBITRARY_CLOCK_GENERATOR_ACCESS

