		// Master bus address width: 26
		.ADDRESS_WIDTH(26+$clog2(128/8)),
		.SMALL_DW(32),
		.WIDE_DW(128),
		.OPT_LITTLE_ENDIAN(1'b0)
		// }}}
	) u_wbu_wbwide_downsz (
